// All four collections arrive as items from Fetch Categories (last in chain)
// We reach back to each node by name

const interests = $('Webhook').first().json.query.interests || '';

const formations = $('Fetch Formations').all().map(i => i.json);
const avisItems  = $('Fetch Avis').all().map(i => i.json);
const skills     = $('Fetch Skills').all().map(i => i.json);
const categories = $('Fetch Categories').all().map(i => i.json);

if (!formations.length) {
  throw new Error('No formations found in database');
}

// Skill lookup map
const skillMap = {};
skills.forEach(s => { skillMap[String(s._id)] = s.name; });

// Category lookup map
const categoryMap = {};
categories.forEach(c => { categoryMap[String(c._id)] = c.nom; });

// Average rating per formation
const ratingMap = {};
avisItems.forEach(a => {
  const fid = String(a.formationId);
  if (!ratingMap[fid]) ratingMap[fid] = { sum: 0, count: 0 };
  ratingMap[fid].sum   += Number(a.note) || 0;
  ratingMap[fid].count += 1;
});

// Build course list string for AI using REF_ID to prevent hallucination
const lines = formations.map((f, index) => {
  const fid     = String(f._id);
  const refId   = index + 1;
  const rating  = ratingMap[fid];
  const avgNote = rating
    ? (rating.sum / rating.count).toFixed(1) + '/5 (' + rating.count + ' avis)'
    : 'Aucun avis';
  const catName = categoryMap[String(f.categorieId)] || 'Non categorise';
  const reqSkillNames = (f.requiredSkills || [])
    .map(sid => skillMap[String(sid)] || String(sid))
    .join(', ') || 'Aucun prerequis';

  return [
    'REF_ID: '       + refId,
    'Titre: '        + (f.titre       || 'N/A'),
    'Description: '  + (f.description || 'N/A'),
    'Categorie: '    + catName,
    'Duree: '        + (f.duree != null ? f.duree + ' h'   : 'N/A'),
    'Prix: '         + (f.prix  != null ? f.prix  + ' TND' : 'N/A'),
    'Note moyenne: ' + avgNote,
    'Prerequis: '    + reqSkillNames
  ].join(' | ');
});

const courseList = lines.join('\n---\n');
const formationIds = formations.map(f => String(f._id));

return [{ json: { interests, courseList, formationIds } }];

const input = $input.first().json;
const validIds = $('Merge and Format').first().json.formationIds || [];

let rec;
try {
  if (typeof input.output === 'object' && input.output !== null) {
    rec = input.output;
  } else {
    const raw = String(input.output || input.text || '');
    const cleaned = raw.replace(/```json\s*|```/gi, '').trim();
    rec = JSON.parse(cleaned);
  }
} catch (e) {
  return [{ json: { success: false, error: 'AI did not return valid JSON' }}];
}

const refId = parseInt(rec.ref_id);

// Handle No Match case
if (refId === 0) {
  return [{ json: {
    success: false,
    error: 'No suitable course found for these interests',
    interests: $('Merge and Format').first().json.interests
  }}];
}

// Validate refId range
if (isNaN(refId) || refId < 1 || refId > validIds.length) {
  return [{ json: {
    success: false,
    error: 'AI returned an invalid REF_ID',
    received_ref_id: rec.ref_id,
    total_available: validIds.length
  }}];
}

const realCourseId = validIds[refId - 1];

return [{ json: {
  success: true,
  recommendation: {
    course_id:            realCourseId,
    course_name:          rec.course_name,
    match_score:          rec.match_score,
    reasoning:            rec.reasoning,
    what_they_will_learn: rec.what_they_will_learn
  }
}}];
